INSERT INTO recipes_ingredients_substitutions (id, ingredient_id, substitute_food_id, note, position, created_at, update_at)
SELECT #{id}, #{ingredientId}, #{substituteFoodId}, #{note}, #{position}, #{timestamp}, #{timestamp}
WHERE EXISTS (SELECT 1 FROM ingredient_foods WHERE id=#{substituteFoodId} AND group_id=#{groupId})
